<?php require 'config.php';$u=require_login();page_start('Members',$u);heading('FIND YOUR PEOPLE','A community of possibility.','Meet fellow learners and the mentors helping them move forward.');$q=mb_substr(trim($_GET['q']??''),0,100);?><form class="search"><input name="q" value="<?=e($q)?>" aria-label="Search members" placeholder="Search names or interests"><button class="button">Search</button></form><div class="grid"><?php $members=rows('SELECT id,name,role,bio,interests,photo FROM users WHERE active=1 AND (name LIKE ? OR interests LIKE ?) ORDER BY name',['%'.$q.'%','%'.$q.'%']);foreach($members as $m):?><article class="card"><div style="margin-bottom:14px;"><?=user_avatar($m, 72)?></div><h2><?=e($m['name'])?></h2><span class="badge"><?=e(ucfirst($m['role']))?></span><p class="body-text"><?=e($m['bio']??'Learning and growing with the community.')?></p><p class="meta"><?=e($m['interests'])?></p><?php if($m['role']==='mentor')echo '<a href="mentorship.php" class="button">Connect with a mentor →</a>';?></article><?php endforeach;if(!$members)echo '<p>No members found.</p>';?></div><?php page_end(); ?>
